-- EcoSindh AI research library
-- Run this entire file in Supabase Dashboard > SQL Editor.
-- Public visitors can SELECT published records only. No public insert/update/delete.

create table if not exists public.research_records (
  id bigint generated by default as identity primary key,
  title text not null,
  agency text not null,
  publication_date date,
  topic text not null,
  record_type text not null check (record_type in
    ('new_publication','older_discovered','agency_update','pending_verification')),
  geography text not null default 'Pakistan',
  sindh_relevance text,
  summary text not null,
  source_url text,
  verification_status text not null default 'needs_link_verification'
    check (verification_status in ('verified_source','needs_link_verification','inaccessible','pending')),
  measurement_period text,
  is_published boolean not null default true,
  created_at timestamptz not null default now()
);

alter table public.research_records enable row level security;
revoke all on public.research_records from anon, authenticated;
grant select on public.research_records to anon, authenticated;
drop policy if exists "Public can read published research" on public.research_records;
create policy "Public can read published research"
on public.research_records for select
to anon, authenticated
using (is_published = true);

-- Initial digest records. source_url is intentionally NULL until the exact
-- original document URL is rechecked and entered; do not replace with guesses.
insert into public.research_records
(title, agency, publication_date, topic, record_type, geography, sindh_relevance, summary, source_url, verification_status, measurement_period)
